def digest(*pieces):
    h = hashlib.sha256()
    for piece in pieces:
        if isinstance(piece, np.ndarray):
            a = np.ascontiguousarray(piece)
            h.update(str((a.dtype.str, a.shape)).encode())
            h.update(a.tobytes())
        else:
            h.update(str(piece).encode('utf-8'))
        h.update(b'\n')

